&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;&lt;a href="https://sheriff.bentoncountyor.gov/linn-benton-alert/&nbsp;"&gt;Sign up for Linn-Benton emergency alerts&lt;/a&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
